INSERT INTO _migration_458_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_agr_b002_001', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which mineral soil particles are the largest and feel gritty when rubbed between the fingers?', 'multiple_choice', NULL, '["A. Sand","B. Clay","C. Silt","D. Humus"]', 'A', 'Sand particles are the largest mineral particles in soil and feel gritty; silt feels smooth and floury, clay is the finest and becomes sticky when wet, and humus is decomposed organic matter rather than a mineral particle at all. Therefore the correct answer is A: Sand.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_002', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following crops is a legume commonly included in crop rotation in Ghana?', 'multiple_choice', NULL, '["A. Maize","B. Cowpea","C. Cassava","D. Plantain"]', 'B', 'Cowpea is a legume whose root nodules host Rhizobium bacteria that fix atmospheric nitrogen into the soil, so it restores fertility for the next crop; maize, cassava and plantain are not legumes and cannot fix nitrogen. Therefore the correct answer is B: Cowpea.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_003', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The dark, decomposed organic matter in topsoil that improves soil fertility is called', 'multiple_choice', NULL, '["A. laterite","B. loam","C. humus","D. gravel"]', 'C', 'Humus is the stable product of microbial decomposition of plant and animal remains; it darkens topsoil, improves water retention and slowly releases nutrients. Loam is a balanced soil texture, laterite is an iron-rich subsoil, and gravel is coarse rock fragments. Therefore the correct answer is C: humus.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_004', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which simple tool is most appropriate for weeding a small school garden?', 'multiple_choice', NULL, '["A. Tractor","B. Combine harvester","C. Boom sprayer","D. Hoe"]', 'D', 'A hoe is a simple hand tool suited to uprooting weeds on small plots; a tractor is used for large-scale land preparation, a combine harvester for harvesting grain, and a boom sprayer for applying agrochemicals, none of which suit a small garden. Therefore the correct answer is D: Hoe.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_005', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'On a fertilizer bag labelled NPK 15-15-15, the letters N, P and K stand for', 'multiple_choice', NULL, '["A. nitrogen, phosphorus and potassium","B. sodium, phosphorus and potassium","C. nitrogen, iron and calcium","D. potassium, nitrogen and phosphorus"]', 'A', 'NPK lists the three primary macronutrients in the fixed order nitrogen (promotes leafy growth), phosphorus (root and seed development) and potassium (disease resistance and water regulation); sodium, iron and calcium are not the primary nutrients named by the NPK grade. Therefore the correct answer is A: nitrogen, phosphorus and potassium.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'State', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_006', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Why do Ghanaian farmers often grow groundnut or cowpea in rotation with maize?', 'multiple_choice', NULL, '["A. The legumes shade the maize from excessive sunlight","B. The legumes fix nitrogen that later benefits the maize crop","C. The legumes release chemicals that repel all maize pests","D. The legumes dry the soil so maize roots grow deeper"]', 'B', 'Legume root nodules contain Rhizobium bacteria which convert inert atmospheric nitrogen into nitrates that remain in the soil after harvest; the following maize crop absorbs this nitrogen, cutting fertilizer costs. The other claims are not the agronomic reason for rotating with legumes. Therefore the correct answer is B: The legumes fix nitrogen that later benefits the maize crop.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_007', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The gradual washing away of dissolved mineral nutrients from the topsoil by percolating rainwater is called', 'multiple_choice', NULL, '["A. erosion","B. mulching","C. leaching","D. capillarity"]', 'C', 'Leaching is the downward movement of soluble nutrients such as nitrates in percolating water, carrying them below the reach of crop roots. Erosion is the physical removal of topsoil particles, mulching is covering the soil surface, and capillarity is the upward movement of water. Therefore the correct answer is C: leaching.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_008', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Ploughing along the contour lines of a sloping field mainly helps to', 'multiple_choice', NULL, '["A. increase the temperature of the topsoil","B. raise the pH of acidic soil","C. kill soil-borne pests before planting","D. reduce soil erosion by slowing run-off water"]', 'D', 'Contour ridges act as small barriers across the slope; they slow surface run-off so rainwater soaks into the soil instead of rushing downhill and carrying the fertile topsoil away. Contour ploughing does not change soil temperature, pH or pest populations. Therefore the correct answer is D: reduce soil erosion by slowing run-off water.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_458_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_458_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_458_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_458_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_458_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_458_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_458_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_458_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_458_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_458_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
